import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {hash,json} from './bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-pharyngeal-mri-native',prep=json(stage+'/PREPARATION.json'),atlas=prep.atlas,objects=atlas+'/.git/objects',file=objects+'/info/alternates';
assert.equal(path.resolve(atlas),path.resolve(stage+'/atlas'));assert(fs.statSync(objects).isDirectory());
const original=fs.readFileSync(file,'utf8'),ordered=[],seen=new Set(),visiting=new Set();
function visit(directory){const resolved=path.resolve(directory),key=resolved.toLowerCase();assert.notEqual(key,path.resolve(objects).toLowerCase());assert(!visiting.has(key),'Cycle in existing alternates');if(seen.has(key))return;assert(fs.statSync(resolved).isDirectory());visiting.add(key);const alt=resolved+'/info/alternates';if(fs.existsSync(alt))for(const entry of fs.readFileSync(alt,'utf8').split(/\r?\n/).filter(Boolean)){assert(!entry.startsWith('"'));visit(path.resolve(resolved,entry));}visiting.delete(key);seen.add(key);ordered.push(resolved.replaceAll('\\','/'));}
for(const p of original.split(/\r?\n/).filter(Boolean))visit(path.resolve(objects,p));assert(ordered.length>1);fs.writeFileSync(stage+'/ALTERNATES_BEFORE.txt',original,{flag:'wx'});fs.writeFileSync(file,ordered.join('\n')+'\n');
const git=args=>spawnSync('git',['--no-replace-objects','-C',atlas,...args],{encoding:'utf8',windowsHide:true,maxBuffer:64000000,env:{...process.env,GIT_OPTIONAL_LOCKS:'0'}});
try{const head=git(['rev-parse','HEAD']),tree=git(['rev-parse','HEAD^{tree}']),check=git(['rev-list','--objects','--all','--missing=print','--no-object-names']);for(const r of [head,tree,check]){assert.equal(r.status,0);assert.equal(r.stderr.trim(),'');}assert.equal(head.stdout.trim(),prep.parent.head);assert.equal(tree.stdout.trim(),prep.parent.tree);assert(!check.stdout.split('\n').some(line=>line.startsWith('?')),'Missing reachable object');fs.writeFileSync(stage+'/ALTERNATES_VERIFIED.json',JSON.stringify({at:new Date().toISOString(),root:atlas,parent:prep.parent,objectStores:ordered.length,reachableObjects:check.stdout.trim().split('\n').length,allReachableObjectsPresent:true,noGitWarnings:true,onlyFreshOwnedCloneMetadataChanged:true,previous:hash(stage+'/ALTERNATES_BEFORE.txt'),current:hash(file),normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({stores:ordered.length,reachableObjects:check.stdout.trim().split('\n').length,head:head.stdout.trim(),warnings:0}));}catch(error){fs.writeFileSync(file,original);throw error;}
